const OrarToti = () => {
  const navigate = useNavigate();
  const { an, grupa } = useParams();

  const [activeDropdown, setActiveDropdown] = useState(null);
  const [selectedGroup, setSelectedGroup] = useState(null);
  const [section, setSection] = useState(null);
  const [scheduleData, setScheduleData] = useState([]);
  const dropdownRefs = useRef([]);

  const [sali, setSali] = useState([]);
  const [dotariSala, setDotariSala] = useState(null);
  const [profesori, setProfesori] = useState([]);
  const [discipline, setDiscipline] = useState([]);

  // Preluare profesori
  const handleProfesoriSelect = (numeProfesor) => {
    setSelectedGroup(numeProfesor);
    setActiveDropdown(null);
    fetch(`http://localhost:34101/orar/profesor/${numeProfesor}`)
      .then((res) => res.json())
      .then((data) => setScheduleData(data))
      .catch((err) => console.error("Eroare la orar profesor:", err));
  };

  // Preluare discipline
  const handleDisciplineSelect = (numeDisciplina) => {
    setSelectedGroup(numeDisciplina);
    setActiveDropdown(null);
    fetch(`http://localhost:34101/orar/disciplina/${numeDisciplina}`)
      .then((res) => res.json())
      .then((data) => setScheduleData(data))
      .catch((err) => console.error("Eroare la orar disciplină:", err));
  };

  // Funcție pentru preluarea profesorilor
  useEffect(() => {
    fetch('http://localhost:34101/profesori')
      .then(res => res.json())
      .then(data => setProfesori(data))
      .catch(err => console.error("Eroare la preluarea profesorilor:", err));
  }, []);

  // Funcție pentru preluarea disciplinelor
  useEffect(() => {
    fetch('http://localhost:34101/discipline')
      .then(res => res.json())
      .then(data => setDiscipline(data))
      .catch(err => console.error("Eroare la preluarea disciplinelor:", err));
  }, []);

  const handleEtajSelect = (etaj) => {
    fetch(`http://localhost:34101/sali/etaj/${etaj}`)
      .then((res) => res.json())
      .then((data) => setSali(data))
      .catch((err) => console.error("Eroare la preluarea sălilor:", err));
  };

  const handleSalaSelect = (numeSala) => {
    setSelectedGroup(numeSala);
    setActiveDropdown(null); // închide dropdownul
    fetch(`http://localhost:34101/orar/sala/${numeSala}`)
      .then((res) => res.json())
      .then((data) => setScheduleData(data))
      .catch((err) => console.error("Eroare la orar sala:", err));
  };

  const handleShowDotari = () => {
    fetch(`http://localhost:34101/sali/nume/${selectedGroup}`)
      .then((res) => res.json())
      .then((data) => setDotariSala(data[0]))
      .catch((err) => console.error("Eroare la dotări:", err));
  };

  const toggleDropdown = (index, e) => {
    e.stopPropagation();
    setActiveDropdown((prev) => (prev === index ? null : index));
    setSelectedGroup(null);
  };

  const handleClickOutside = (event) => {
    if (dropdownRefs.current.every((ref) => ref && !ref.contains(event.target))) {
      setActiveDropdown(null);
    }
  };

  useEffect(() => {
    document.addEventListener("click", handleClickOutside);
    return () => {
      document.removeEventListener("click", handleClickOutside);
    };
  }, []);

  useEffect(() => {
    if (an && grupa) {
      const anLabel = `Anul ${an}`;
      setSelectedGroup(`${anLabel} - ${grupa}`);
      setSection("studenti");

      const url = `http://localhost:34101/orar/grupa/${an}/${grupa}`;
      fetch(url)
        .then((res) => res.json())
        .then((data) => setScheduleData(data))
        .catch((err) => {
          console.error("Eroare la preluarea orarului:", err);
        });
    }
  }, [an, grupa]);

  const buttons = [
    {
      label: "Anul 1",
      icon: "1️⃣",
      options: ["A1", "A2", "A3", "A4", "A5", "B1", "B2", "B3", "B4", "E1", "E2", "E3", "I1X1", "I1X2", "I1X3", "I1X4"],
    },
    {
      label: "Anul 2",
      icon: "2️⃣",
      options: ["A1", "A2", "A3", "A4", "A5", "B1", "B2", "B3", "B4", "E1", "E2", "E3", "I1X1", "I1X2", "I1X3", "I1X4"],
    },
    {
      label: "Anul 3",
      icon: "3️⃣",
      options: ["A1", "A2", "A3", "A4", "A5", "B1", "B2", "B3", "B4", "E1", "E2", "E3", "X"]
    },
    {
      label: "Master Anul 1",
      icon: "🎓",
      options: [
        "Inteligența Artificială și Optimizare",
        "Ingineria Sistemelor Soft",
        "Lingvistica Computațională",
        "Studii Avansate în Informatică",
        "Sisteme Distribuite",
        "Securitatea Informațiilor",
      ],
    },
    {
      label: "Master Anul 2",
      icon: "🎓",
      options: [
        "Inteligența Artificială și Optimizare",
        "Ingineria Sistemelor Soft",
        "Lingvistica Computațională",
        "Studii Avansate în Informatică",
        "Sisteme Distribuite",
        "Securitatea Informațiilor",
      ],
    },
  ];

  const etaje = [
    {
      label: "Parter",
      icon: "🏢",
      sali: ["C2", "C112", "C210"],
    },
    {
      label: "Etaj 1",
      icon: "🧱",
      sali: ["C308", "C309"],
    },
    {
      label: "Etaj 2",
      icon: "🏬",
      sali: ["C401", "C403", "C405", "C409", "C411", "C412", "C413"],
    },
    {
      label: "Etaj 7",
      icon: "🌇",
      sali: ["C901", "C903"],
    },
  ];

  const handleGroupSelect = (anLabel, grupa) => {
    const anNumber = anLabel.replace("Anul ", "").trim();
    navigate(`/app/orar/studenti/${anNumber}/${grupa}`);
  };

  return (
    <div className="orar-container">
      {selectedGroup ? (
        <div className="orar-afisat">
          <h3>Orar pentru {selectedGroup}</h3>

          <ScheduleTable
            schedule={scheduleData}
            title={`Orar pentru ${selectedGroup}`}
            showSala={true}
          />

          <button
            className="orar-button inapoi"
            onClick={() => {
              setSelectedGroup(null);
              setScheduleData([]);
              navigate("/app/orar");
            }}
          >
            🔙 Înapoi
          </button>
        </div>
      ) : (
        <>
          <div className="orar-titlu">
            <h1>Orar</h1>
            {!section && <h2>Alege o categorie</h2>}
            {section === "studenti" && <h2>Alege anul și grupa</h2>}
          </div>

          {!section && (
            <div className="orar-buttons">
              <button className="orar-button" onClick={() => setSection("studenti")}>
                🎓 Orar Studenți
              </button>
              <button className="orar-button" onClick={() => setSection("profesori")}>
                👨‍🏫 Orar Profesori
              </button>
              <button className="orar-button" onClick={() => setSection("sali")}>
                🏫 Orar Săli
              </button>
              <button className="orar-button" onClick={() => setSection("discipline")}>
                📚 Orar Discipline
              </button>
            </div>
          )}

          {section === "studenti" && (
            <>
              <div className="orar-buttons">
                {buttons.map((button, index) => (
                  <div
                    className="dropdown-container"
                    key={index}
                    ref={(el) => (dropdownRefs.current[index] = el)}
                  >
                    <button className="orar-button" onClick={(e) => toggleDropdown(index, e)}>
                      <span className="icon">{button.icon}</span>
                      {button.label}
                    </button>

                    {activeDropdown === index && (
                      <div className="dropdown-menu">
                        {button.options.map((option, i) => (
                          <div key={i}>
                            <button
                              className="dropdown-item"
                              onClick={() => handleGroupSelect(button.label, option)}
                            >
                              {option}
                            </button>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ))}
              </div>

              <div className="inapoi-container">
                <button
                  className="orar-button inapoi"
                  onClick={() => {
                    setSection(null);
                    setActiveDropdown(null);
                    navigate("/app/orar");
                  }}
                >
                  🔙 Înapoi
                </button>
              </div>
            </>
          )}

          {section === "profesori" && profesori.length > 0 && (
            <div className="orar-buttons">
              {profesori.map((profesor, index) => (
                <button
                  key={index}
                  className="orar-button"
                  onClick={() => handleProfesoriSelect(profesor.nume)}
                >
                  👨‍🏫 {profesor.nume}
                </button>
              ))}
            </div>
          )}

          {section === "discipline" && discipline.length > 0 && (
            <div className="orar-buttons">
              {discipline.map((disciplina, index) => (
                <button
                  key={index}
                  className="orar-button"
                  onClick={() => handleDisciplineSelect(disciplina.nume)}
                >
                  📚 {disciplina.nume}
                </button>
              ))}
            </div>
          )}

          {section === "sali" && !selectedGroup && (
            <>
              <div className="orar-buttons">
                {etaje.map((etaj, index) => (
                  <div
                    className="dropdown-container"
                    key={index}
                    ref={(el) => (dropdownRefs.current[index] = el)}
                  >
                    <button className="orar-button" onClick={(e) => toggleDropdown(index, e)}>
                      <span className="icon">{etaj.icon}</span>
                      {etaj.label}
                    </button>

                    {activeDropdown === index && (
                      <div className="dropdown-menu">
                        {etaj.sali.map((sala, i) => (
                          <div key={i}>
                            <button className="dropdown-item" onClick={() => handleSalaSelect(sala)}>
                              {sala}
                            </button>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ))}
              </div>

              <div className="inapoi-container">
                <button
                  className="orar-button inapoi"
                  onClick={() => {
                    setSection(null);
                    setActiveDropdown(null);
                    navigate("/app/orar");
                  }}
                >
                  🔙 Înapoi
                </button>
              </div>
            </>
          )}

          {section === "sali" && sali.length > 0 && !selectedGroup && (
            <div className="orar-buttons">
              {sali.map((sala, index) => (
                <button
                  key={index}
                  className="orar-button"
                  onClick={() => handleSalaSelect(sala.nume)}
                >
                  🧾 {sala.nume}
                </button>
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
};
